#ifdef PHOTON_CLOUD_SECONDARY_EXTENT_PROBE
// ShaderLOD standalone probe: preserve B15's ratio and operation order.
float clouds_cumulus_secondary_extent_scale(uint step_count, uint original_steps) {
    return (float(step_count) / float(original_steps)) *
            (exp2(float(original_steps)) - 1.0) / (exp2(float(step_count)) - 1.0);
}

#endif // PHOTON_CLOUD_SECONDARY_EXTENT_PROBE
float clouds_cumulus_optical_depth(
    vec3 ray_origin,
    vec3 ray_dir,
    float dither,
    uint step_count,
#ifdef PHOTON_CLOUD_SECONDARY_EXTENT_PROBE
    uint original_steps,
    float extent_scale
#else
    uint original_steps
#endif // PHOTON_CLOUD_SECONDARY_EXTENT_PROBE
) {

#ifdef PHOTON_CLOUD_SECONDARY_EXTENT_PROBE
        step_length *= extent_scale;
#else
        step_length *= (float(step_count) / float(original_steps)) *
            (exp2(float(original_steps)) - 1.0) / (exp2(float(step_count)) - 1.0);
#endif // PHOTON_CLOUD_SECONDARY_EXTENT_PROBE

#endif // SHADERLOD_CLOUD_MODE
